// Private construction-only microbenchmark. No game, RPH, graphics, or audio IO.
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Web.Script.Serialization;
using RichAudio.Settings.InGame;

public static class MenuFrameCost
{
    private const int Width=1920,Height=1080,Warmup=200,Frames=1000;
    private static long sink;
    private sealed class Sample
    {
        public double BuildUs,PresentUs,TotalUs;
        public int BuildDraws,PresentedDraws,Hits;
    }
    private static Sample One(AcousticMenuModel menu,MenuStatus status,MenuTransitionState state)
    {
        long start=Stopwatch.GetTimestamp();
        MenuFrame built=menu.BuildFrame(Width,Height,status);
        long middle=Stopwatch.GetTimestamp();
#if POINTER
        MenuFrame shown=MenuTransition.Present(built,state,Width,Height,180f,500f,true);
#else
        MenuFrame shown=MenuTransition.Present(built,state,Width,Height);
#endif
        long end=Stopwatch.GetTimestamp();
        sink+=shown.Commands.Count+shown.Regions.Count;
        return new Sample{BuildUs=(middle-start)*1000000d/Stopwatch.Frequency,
            PresentUs=(end-middle)*1000000d/Stopwatch.Frequency,
            TotalUs=(end-start)*1000000d/Stopwatch.Frequency,
            BuildDraws=built.Commands.Count,PresentedDraws=shown.Commands.Count,Hits=shown.Regions.Count};
    }
    private static Dictionary<string,object> Stats(double[] raw)
    {
        double[] sorted=(double[])raw.Clone();Array.Sort(sorted);
        return new Dictionary<string,object>{{"medianUs",(sorted[499]+sorted[500])/2},
            {"p95Us",sorted[949]},{"p99Us",sorted[989]},{"maxUs",sorted[999]},
            {"rawUs",raw}};
    }
    public static int Main(string[] args)
    {
        if(args.Length!=3)throw new ArgumentException("Output JSON, revision label, call label required");
        var process=Process.GetCurrentProcess();
        var menu=new AcousticMenuModel();menu.Open(MenuPreferences.Defaults);
        var status=MenuStatus.Measured("balanced","balanced","cpu","cpu","CPU fixture device","",16,0,
            "Engine report. Deadline misses: 0; dropped GPU results: 0. Output enabled. Early reflections on.",true,1,true);
#if BASELINE
        const int duration=220;
#else
        const int duration=260;
#endif
        var transition=new MenuTransition(duration);transition.SetOpen(true,0);
        MenuTransitionState state=transition.Sample(260);
        if(!state.FullyOpen)throw new Exception("260 ms sample must be fully open");
        DateTime started=DateTime.UtcNow;
        double cpuBeforeCold=process.TotalProcessorTime.TotalMilliseconds;
        Sample cold=One(menu,status,state);
        double cpuAfterCold=process.TotalProcessorTime.TotalMilliseconds;
        for(int i=0;i<Warmup;i++)One(menu,status,state);
        GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();
        var build=new double[Frames];var present=new double[Frames];var total=new double[Frames];
        int[] gcBefore={GC.CollectionCount(0),GC.CollectionCount(1),GC.CollectionCount(2)};
        double cpuBefore=process.TotalProcessorTime.TotalMilliseconds;
        long batchStart=Stopwatch.GetTimestamp();
        for(int i=0;i<Frames;i++)
        {
            Sample sample=One(menu,status,state);build[i]=sample.BuildUs;present[i]=sample.PresentUs;total[i]=sample.TotalUs;
            if(sample.BuildDraws!=cold.BuildDraws||sample.PresentedDraws!=cold.PresentedDraws||sample.Hits!=cold.Hits)
                throw new Exception("Draw/hit counts changed within static workload");
        }
        long batchEnd=Stopwatch.GetTimestamp();
        double cpuAfter=process.TotalProcessorTime.TotalMilliseconds;
        int[] gcDelta={GC.CollectionCount(0)-gcBefore[0],GC.CollectionCount(1)-gcBefore[1],GC.CollectionCount(2)-gcBefore[2]};
        var result=new Dictionary<string,object>{{"schemaVersion",1},{"revision",args[1]},{"callScope",args[2]},
            {"pid",process.Id},{"startedAtUtc",started.ToString("o")},{"completedAtUtc",DateTime.UtcNow.ToString("o")},
            {"runtime",Environment.Version.ToString()},{"is64BitProcess",Environment.Is64BitProcess},
            {"width",Width},{"height",Height},{"configuredTransitionDurationMs",duration},{"stateSampleTimeMs",260},
            {"warmupFrames",Warmup},{"warmFrames",Frames},{"stopwatchFrequency",Stopwatch.Frequency},
            {"coldBuildUs",cold.BuildUs},{"coldPresentUs",cold.PresentUs},{"coldTotalUs",cold.TotalUs},
            {"coldProcessCpuDeltaMs",cpuAfterCold-cpuBeforeCold},
            {"buildDrawCommands",cold.BuildDraws},{"presentedDrawCommands",cold.PresentedDraws},{"hitRegions",cold.Hits},
            {"warmBuild",Stats(build)},{"warmPresent",Stats(present)},{"warmTotal",Stats(total)},
            {"warmBatchElapsedMs",(batchEnd-batchStart)*1000d/Stopwatch.Frequency},
            {"warmProcessCpuDeltaMs",cpuAfter-cpuBefore},{"warmProcessCpuUsPerFrame",(cpuAfter-cpuBefore)*1000d/Frames},
            {"warmGcCollections",gcDelta},{"sink",sink}};
        File.WriteAllText(args[0],new JavaScriptSerializer{MaxJsonLength=1048576}.Serialize(result));
        Console.WriteLine(args[1]+" / "+args[2]+" -> "+args[0]);return 0;
    }
}

