[CmdletBinding()]
param()
$ErrorActionPreference='Stop'
$repo='<repo>'
$out=Join-Path $repo ('.local\menu01-cost-'+[DateTime]::UtcNow.ToString('yyyyMMddTHHmmssZ'))
[IO.Directory]::CreateDirectory($out)|Out-Null
$baseline='1f496a7e05c978c4b2eade0524055ac93b56e413'
$imported='6a515f21b956e62cf86945cbdd3f7e86856ec807'
$compiler=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
$names=@('AcousticMenuLayout.cs','AcousticMenuModel.cs','HostMenuStatus.cs','MenuContracts.cs','MenuInputRouter.cs','MenuTransition.cs')
function Sha([byte[]]$bytes){$sha=[Security.Cryptography.SHA256]::Create();try{return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function GitBytes([string]$revision,[string]$path,[string]$target){
    $info=[Diagnostics.ProcessStartInfo]::new('git');$info.WorkingDirectory=$repo
    $info.Arguments='show '+$revision+':'+$path;$info.UseShellExecute=$false;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$info.CreateNoWindow=$true
    $proc=[Diagnostics.Process]::Start($info);$stream=[IO.File]::Create($target)
    try{$proc.StandardOutput.BaseStream.CopyTo($stream)}finally{$stream.Dispose()}
    $err=$proc.StandardError.ReadToEnd();$proc.WaitForExit();if($proc.ExitCode-ne0){throw $err}
}
$closure=@()
foreach($variant in @('baseline','current','imported')){
    $dir=Join-Path $out $variant;[IO.Directory]::CreateDirectory($dir)|Out-Null
    foreach($name in $names){
        $path='src/acoustics/settings/InGame/'+$name;$target=Join-Path $dir $name
        if($variant-eq'current'){[IO.File]::Copy((Join-Path $repo $path),$target)}
        else{GitBytes $(if($variant-eq'baseline'){$baseline}else{$imported}) $path $target}
        $bytes=[IO.File]::ReadAllBytes($target);$text=[Text.Encoding]::UTF8.GetString($bytes)
        $lf=[Text.Encoding]::UTF8.GetBytes($text.Replace("`r`n","`n"))
        $revision=if($variant-eq'baseline'){$baseline}elseif($variant-eq'imported'){$imported}else{$null}
        $blob=if($revision){(& git -C $repo rev-parse ($revision+':'+$path)).Trim()}else{(& git -C $repo hash-object --no-filters -- $target).Trim()}
        $closure += [ordered]@{variant=$variant;path=$path;gitRevision=$revision;gitBlob=$blob;rawSha256=(Sha $bytes);lfNormalizedSha256=(Sha $lf);byteLength=$bytes.Length;crlfPairs=([regex]::Matches($text,"`r`n")).Count;lfCharacters=([regex]::Matches($text,"`n")).Count}
    }
}
# Capture bridge provenance without compiling or loading RPH.
foreach($variant in @('baseline','current','imported')){
    $path='src/acoustics/bridge/Rph/InGameMenu.Rph.cs';$target=Join-Path $out ($variant+'\InGameMenu.Rph.cs.provenance')
    if($variant-eq'current'){[IO.File]::Copy((Join-Path $repo $path),$target)}
    else{GitBytes $(if($variant-eq'baseline'){$baseline}else{$imported}) $path $target}
    $bytes=[IO.File]::ReadAllBytes($target);$text=[Text.Encoding]::UTF8.GetString($bytes)
    $revision=if($variant-eq'baseline'){$baseline}elseif($variant-eq'imported'){$imported}else{$null}
    $blob=if($revision){(& git -C $repo rev-parse ($revision+':'+$path)).Trim()}else{(& git -C $repo hash-object --no-filters -- $target).Trim()}
    $closure += [ordered]@{variant=$variant;path=$path;provenanceOnly=$true;gitRevision=$revision;gitBlob=$blob;rawSha256=(Sha $bytes);lfNormalizedSha256=(Sha ([Text.Encoding]::UTF8.GetBytes($text.Replace("`r`n","`n"))));byteLength=$bytes.Length;crlfPairs=([regex]::Matches($text,"`r`n")).Count;lfCharacters=([regex]::Matches($text,"`n")).Count}
}
$harness=Join-Path $PSScriptRoot 'MenuFrameCost.cs';[IO.File]::Copy($harness,(Join-Path $out 'MenuFrameCost.cs'))
$builds=@()
foreach($spec in @(@{name='baseline';source='baseline';define='BASELINE'},@{name='current-common';source='current';define='COMMON'},@{name='current-pointer';source='current';define='POINTER'})){
    $sources=@($names|ForEach-Object{Join-Path (Join-Path $out $spec.source) $_})
    $exe=Join-Path $out ($spec.name+'.exe')
    $opts=@('/nologo','/optimize+','/warnaserror+','/langversion:5','/platform:x64','/r:System.Web.Extensions.dll','/target:exe','/main:MenuFrameCost',('/define:'+$spec.define),('/out:'+$exe))
    $log=(& $compiler @opts @sources $harness 2>&1 | Out-String)
    [IO.File]::WriteAllText((Join-Path $out ($spec.name+'-compile.log')),$log)
    if($LASTEXITCODE-ne0){throw ('Compilation failed: '+$spec.name+' '+$log)}
    $builds += [ordered]@{name=$spec.name;compiler=$compiler;compilerVersion=(Get-Item -LiteralPath $compiler).VersionInfo.FileVersion;options=$opts;exe=$exe;exeSha256=(Sha ([IO.File]::ReadAllBytes($exe)))}
}
$manifest=[ordered]@{schemaVersion=1;preparedAtUtc=[DateTime]::UtcNow.ToString('o');repo=$repo;out=$out;workingHead=(& git -C $repo rev-parse HEAD).Trim();baseline=$baseline;imported=$imported;harnessSha256=(Sha ([IO.File]::ReadAllBytes($harness)));sourceClosure=$closure;builds=$builds;measurementStarted=$false}
$manifest|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $out 'prepared.json') -Encoding UTF8
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'latest.txt'),$out)
Write-Output $out
